		t.Fatalf("exit code = %d, want 0", code)
	}
	if stderr.Len() != 0 {
		t.Fatalf("stderr = %q, want empty", stderr.String())
	}
	assertWindowLines(t, stdout.String(), []windowLine{
		{Key: "�", Start: 0, End: 1000, Count: 2, Sum: 5},
	})
}

