package edgefleet

import (
	"bytes"
	"encoding/json"
	"math"
	"reflect"
	"strings"
	"testing"
)

func runAggregate(t *testing.T, input string, window int64) (string, string, error) {
	t.Helper()
	var stdout, stderr bytes.Buffer
	err := RunAggregate(strings.NewReader(input), window, &stdout, &stderr)
	return stdout.String(), stderr.String(), err
}

func TestAggregateBasicClosureAndOrder(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"sensor-b","time":800,"value":-2}`,
		`{"type":"event","key":"sensor-a","time":1200,"value":5}`,
		``, // blank line must be ignored
		`{"type":"event","key":"sensor-a","time":1500,"value":7}`,
		`{"type":"watermark","time":1000}`,
		`{"type":"watermark","time":1999}`, // does not close [1000,2000)
		`{"type":"watermark","time":2000}`,
	}, "\n")
	stdout, stderr, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("unexpected stderr: %q", stderr)
	}
	want := strings.Join([]string{
		`{"key":"sensor-b","start":0,"end":1000,"count":1,"sum":-2}`,
		`{"key":"sensor-a","start":1000,"end":2000,"count":2,"sum":12}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

func TestAggregateClosureOrderByEndThenUTF8Key(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"中","time":500,"value":1}`,
		`{"type":"event","key":"é","time":100,"value":1}`,
		`{"type":"event","key":"A","time":900,"value":1}`,
		`{"type":"event","key":"A","time":1200,"value":1}`,
		`{"type":"event","key":"é","time":1100,"value":1}`,
		`{"type":"watermark","time":2000}`,
	}, "\n")
	stdout, _, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	lines := strings.Split(strings.TrimSuffix(stdout, "\n"), "\n")
	wantKeys := []string{"A", "é", "中", "A", "é"} // end=1000 byte-order, then end=2000
	wantEnds := []int64{1000, 1000, 1000, 2000, 2000}
	var gotKeys []string
	var gotEnds []int64
	for _, line := range lines {
		var result AggregateResult
		if err := json.Unmarshal([]byte(line), &result); err != nil {
			t.Fatalf("invalid output line %q: %v", line, err)
		}
		gotKeys = append(gotKeys, result.Key)
		gotEnds = append(gotEnds, result.End)
	}
	if !reflect.DeepEqual(gotKeys, wantKeys) || !reflect.DeepEqual(gotEnds, wantEnds) {
		t.Fatalf("closure order = %v ends %v, want %v ends %v\nfull output:\n%s", gotKeys, gotEnds, wantKeys, wantEnds, stdout)
	}
}

func TestAggregateNoWatermarkNoOutput(t *testing.T) {
	input := `{"type":"event","key":"k","time":1,"value":1}` + "\n"
	stdout, _, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stdout != "" {
		t.Fatalf("open windows must not flush at EOF, got %q", stdout)
	}
}

func TestAggregateRepeatedAndJumpingWatermark(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"k","time":100,"value":2}`,
		`{"type":"watermark","time":1000}`,
		`{"type":"watermark","time":1000}`,                 // repeat: no duplicate output
		`{"type":"event","key":"k","time":1000,"value":3}`, // boundary: next window
		`{"type":"event","key":"k","time":2500,"value":4}`,
		`{"type":"watermark","time":5000}`, // jump closes 1000 and 2000 windows
	}, "\n")
	stdout, _, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := strings.Join([]string{
		`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
		`{"key":"k","start":1000,"end":2000,"count":1,"sum":3}`,
		`{"key":"k","start":2000,"end":3000,"count":1,"sum":4}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

func TestAggregateLateAndBoundaryEvents(t *testing.T) {
	input := strings.Join([]string{
		``, // line 1 blank
		`{"type":"watermark","time":1000}`,
		``, // line 3 blank
		`{"type":"event","key":"k","time":999,"value":1}`,  // late, line 4
		`{"type":"event","key":"k","time":1000,"value":5}`, // equal to watermark: valid
	}, "\n")
	stdout, stderr, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stdout != "" {
		t.Fatalf("window [1000,2000) must stay open, got %q", stdout)
	}
	wantErr := "line 4: late event time=999 below current watermark 1000, skipped\n"
	if stderr != wantErr {
		t.Fatalf("stderr = %q, want %q", stderr, wantErr)
	}
}

func TestAggregatePriorOutputRetainedOnFatalError(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"k","time":0,"value":1}`,
		`{"type":"watermark","time":1000}`,
		`not json`,
	}, "\n")
	stdout, _, err := runAggregate(t, input, 1000)
	if err == nil {
		t.Fatal("expected non-nil error for malformed JSON")
	}
	if got := stdout; got != `{"key":"k","start":0,"end":1000,"count":1,"sum":1}`+"\n" {
		t.Fatalf("earlier output must be retained, got %q", got)
	}
}

func TestAggregateDeterministic(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"zeta","time":200,"value":1}`,
		`{"type":"event","key":"alpha","time":100,"value":-1}`,
		`{"type":"event","key":"alpha","time":1200,"value":2}`,
		`{"type":"event","key":"zeta","time":1100,"value":3}`,
		`{"type":"event","key":"mid","time":900,"value":0}`,
		`{"type":"watermark","time":3000}`,
	}, "\n")
	first, _, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	second, _, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if first != second {
		t.Fatalf("repeated runs must be identical:\n%s\nvs\n%s", first, second)
	}
}

func TestAggregateInvalidWindow(t *testing.T) {
	for _, w := range []int64{0, -1, math.MinInt64} {
		if err := RunAggregate(strings.NewReader(""), w, &bytes.Buffer{}, &bytes.Buffer{}); err == nil {
			t.Fatalf("expected error for window %d", w)
		}
	}
}

func TestAggregateFatalRecordErrors(t *testing.T) {
	cases := []struct {
		name      string
		input     string
		wantLine  int
		wantInMsg string
	}{
		{"malformed json", "{not json\n", 1, "invalid JSON"},
		{"missing type", `{"key":"k","time":1,"value":1}` + "\n", 1, `"type"`},
		{"non-string type", `{"type":7,"key":"k","time":1,"value":1}` + "\n", 1, `"type"`},
		{"unknown type", `{"type":"heartbeat"}` + "\n", 1, "unknown record type"},
		{"missing key", `{"type":"event","time":1,"value":1}` + "\n", 1, `"key"`},
		{"empty key", `{"type":"event","key":"","time":1,"value":1}` + "\n", 1, "non-empty"},
		{"numeric key", `{"type":"event","key":5,"time":1,"value":1}` + "\n", 1, `"key"`},
		{"missing time", `{"type":"event","key":"k","value":1}` + "\n", 1, `"time"`},
		{"negative time", `{"type":"event","key":"k","time":-1,"value":1}` + "\n", 1, "non-negative"},
		{"fractional time", `{"type":"event","key":"k","time":1.5,"value":1}` + "\n", 1, `"time"`},
		{"string time", `{"type":"event","key":"k","time":"1","value":1}` + "\n", 1, `"time"`},
		{"null time", `{"type":"event","key":"k","time":null,"value":1}` + "\n", 1, `"time"`},
		{"time too large", `{"type":"event","key":"k","time":9223372036854775808,"value":1}` + "\n", 1, "range"},
		{"missing value", `{"type":"event","key":"k","time":1}` + "\n", 1, `"value"`},
		{"boolean value", `{"type":"event","key":"k","time":1,"value":true}` + "\n", 1, `"value"`},
		{"value too large", `{"type":"event","key":"k","time":1,"value":9223372036854775808}` + "\n", 1, "range"},
		{"watermark missing time", `{"type":"watermark"}` + "\n", 1, `"time"`},
		{"watermark negative", `{"type":"watermark","time":-5}` + "\n", 1, "non-negative"},
		{"watermark regression", `{"type":"watermark","time":10}` + "\n" + `{"type":"watermark","time":9}` + "\n", 2, "backwards"},
		{
			"window end overflow",
			`{"type":"event","key":"k","time":9223372036854775807,"value":1}` + "\n",
			1, "window end overflow",
		},
		{
			"cumulative sum overflow",
			`{"type":"event","key":"k","time":1,"value":9223372036854775807}` + "\n" +
				`{"type":"event","key":"k","time":2,"value":1}` + "\n",
			2, "sum overflow",
		},
		{
			"cumulative sum underflow",
			`{"type":"event","key":"k","time":1,"value":-9223372036854775808}` + "\n" +
				`{"type":"event","key":"k","time":2,"value":-1}` + "\n",
			2, "sum overflow",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, _, err := runAggregate(t, tc.input, 3)
			if err == nil {
				t.Fatal("expected error, got nil")
			}
			inputErr, ok := err.(*InputError)
			if !ok {
				t.Fatalf("expected *InputError, got %T: %v", err, err)
			}
			if inputErr.Line != tc.wantLine {
				t.Errorf("line = %d, want %d", inputErr.Line, tc.wantLine)
			}
			if !strings.Contains(inputErr.Reason, tc.wantInMsg) {
				t.Errorf("reason = %q, want substring %q", inputErr.Reason, tc.wantInMsg)
			}
		})
	}
}

func TestAggregateErroredRecordProducesNoWindow(t *testing.T) {
	// First event valid, second invalid within same window: window must not be emitted.
	input := strings.Join([]string{
		`{"type":"event","key":"k","time":1,"value":1}`,
		`{"type":"event","key":"k","time":2,"value":"oops"}`,
		`{"type":"watermark","time":1000}`,
	}, "\n")
	stdout, _, err := runAggregate(t, input, 1000)
	if err == nil {
		t.Fatal("expected error")
	}
	if stdout != "" {
		t.Fatalf("errored record must not contribute to window results, got %q", stdout)
	}
}

func TestAggregateExtraFieldsAccepted(t *testing.T) {
	input := `{"type":"event","key":"k","time":1,"value":1,"source":"lab"}` + "\n" +
		`{"type":"watermark","time":1000,"note":"jump"}` + "\n"
	stdout, _, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := `{"key":"k","start":0,"end":1000,"count":1,"sum":1}` + "\n"
	if stdout != want {
		t.Fatalf("got %q, want %q", stdout, want)
	}
}

func TestAggregateWatermarkZero(t *testing.T) {
	input := `{"type":"watermark","time":0}` + "\n" +
		`{"type":"event","key":"k","time":0,"value":1}` + "\n"
	stdout, _, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stdout != "" {
		t.Fatalf("watermark 0 closes nothing; got %q", stdout)
	}
}

package edgefleet

import (
	"bytes"
	"fmt"
	"strings"
	"testing"
	"time"
)

// This file guards the cost of collecting physical lines, not their results.
// The result contract for long records split across arbitrary reads lives in
// aggregate_long_record_test.go and aggregate_chunked_input_test.go. What is
// pinned here is the complexity: when a legal record with a very long key
// arrives one or a few bytes per Read, line collection must cost about one
// newline scan per input byte -- linear in the cumulative input byte count
// and read count -- rather than one scan per Read over the whole accumulated
// tail, which is quadratic in the line length.

// singleByteCuts lists a cut before every byte except the first, the schedule
// that made the old rescanner quadratic.
func singleByteCuts(n int) []int {
	cuts := make([]int, 0, n-1)
	for at := 1; at < n; at++ {
		cuts = append(cuts, at)
	}
	return cuts
}

// bestSingleByteTime measures repeated one-byte-per-Read passes in growing
// batches until a batch spans at least minBatch, returning the best
// (minimum-noise) average per pass. Comparing two streams of the same byte
// length under the same schedule makes the ratio independent of the
// machine's absolute speed.
func bestSingleByteTime(t *testing.T, input string, minBatch time.Duration) time.Duration {
	t.Helper()
	cuts := singleByteCuts(len(input))
	iters := 1
	best := time.Duration(1<<63 - 1)
	for attempt := 0; attempt < 6; attempt++ {
		begin := time.Now()
		for i := 0; i < iters; i++ {
			var out, late bytes.Buffer
			if err := RunAggregate(newChunkReader(input, cuts...), 1000, &out, &late); err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
		}
		batch := time.Since(begin)
		if avg := batch / time.Duration(iters); avg < best {
			best = avg
		}
		if batch >= minBatch {
			return best
		}
		// Run long enough to rise above scheduler noise, then try again.
		iters *= 4
	}
	return best
}

// TestAggregateLineCollectionCostFollowsBytesNotLineLength is the complexity
// guard. Two inputs have essentially the SAME total byte count and arrive
// through the SAME number of one-byte Reads; they differ only in whether the
// bytes form one very long physical record or thousands of short ones. A
// linear collector scans every byte about once either way (plus read-call
// overhead, identical per byte), so the two timings are comparable. The old
// collector rescanned the whole pending tail after every Read, i.e. about
// L*L/2 comparisons for one L-byte line versus only N*m/2 for N bytes split
// into m-byte lines, making the long-line input hundreds of times slower
// despite the identical byte and read counts.
func TestAggregateLineCollectionCostFollowsBytesNotLineLength(t *testing.T) {
	if testing.Short() {
		t.Skip("timing guard skipped in -short mode")
	}
	const target = 200 * 1024

	// One long event record (long multibyte key) closed by a watermark.
	longKey := longKey(longKeySuffixA, target)
	oneLongLine := strings.Join([]string{
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":7}`, longKey),
		`{"type":"watermark","time":1000}`,
		``,
	}, "\n")

	// The same number of bytes as many short newline-terminated records, all
	// merging into one short-key window, closed by a watermark.
	shortRecord := `{"type":"event","key":"短","time":100,"value":1}` + "\n"
	var b strings.Builder
	for b.Len()+len(shortRecord) < target {
		b.WriteString(shortRecord)
	}
	b.WriteString(`{"type":"watermark","time":1000}` + "\n")
	manyShortLines := b.String()

	if len(oneLongLine) < target {
		t.Fatalf("test setup: long input is only %d bytes, want >= %d", len(oneLongLine), target)
	}
	// The two streams must be genuinely the same order of size; otherwise the
	// ratio would measure byte count rather than line layout.
	if got := len(oneLongLine); got > target*2 || got < target {
		t.Fatalf("test setup: long input %d bytes vs short input %d bytes", got, len(manyShortLines))
	}

	// The timed long-line delivery must also stay correct: the whole key
	// survives one-byte arrival and the watermark closes its window.
	var out, late bytes.Buffer
	if err := RunAggregate(newChunkReader(oneLongLine, singleByteCuts(len(oneLongLine))...), 1000, &out, &late); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	wantWindow := fmt.Sprintf(`{"key":%q,"start":0,"end":1000,"count":1,"sum":7}`+"\n", longKey)
	if out.String() != wantWindow {
		t.Fatalf("single-byte long-line output mismatch:\n got: %q\nwant: %q", out.String(), wantWindow)
	}
	if late.String() != "" {
		t.Fatalf("unexpected late notices: %q", late.String())
	}

	longAvg := bestSingleByteTime(t, oneLongLine, 30*time.Millisecond)
	shortAvg := bestSingleByteTime(t, manyShortLines, 30*time.Millisecond)

	// Linear collection: comparable cost for equal bytes and equal reads.
	// The short stream parses thousands of records (more callbacks), the long
	// stream copies/grows one large buffer (more copies), so either may win;
	// allow a generous factor either way. The quadratic rescanner made the
	// long stream hundreds of times slower.
	const factor = 6.0
	if ratio := float64(longAvg) / float64(shortAvg); ratio > factor {
		t.Fatalf("line collection cost grows with line length at fixed byte/read count: "+
			"one %d-byte line took %v/pass, %d bytes of short lines took %v/pass "+
			"(long/short ratio %.2f, want <= %.1f)",
			len(oneLongLine), longAvg, len(manyShortLines), shortAvg, ratio, factor)
	}
	// Absolute backstop: ~200 KiB delivered one byte at a time must finish
	// promptly with a linear collector, even on a slow, contended machine.
	if longAvg > 2*time.Second {
		t.Fatalf("single-byte processing of %d bytes took %v/pass, want under 2s", len(oneLongLine), longAvg)
	}
}

// TestAggregateLineCollectionAlternatingChunksLinear interleaves long and
// short records and alternates the read size between one byte and a few
// kilobytes, so the cursor that resumes the newline search must repeatedly
// skip already-searched long tails and then find newlines inside freshly
// appended bytes. Output must equal the one-shot reference; this guards
// correctness of the resume cursor under mixed chunking, the timing ratio is
// covered by the test above.
func TestAggregateLineCollectionAlternatingChunksLinear(t *testing.T) {
	keyA := longKey(longKeySuffixA, 64*1024)
	keyB := longKey(longKeySuffixB, 64*1024)
	lines := []string{
		``,
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":2}`, "短"),
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":10}`, keyA),
		`{"type":"watermark","time":500}`,
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":7}`, keyB),
		``,
		fmt.Sprintf(`{"type":"event","key":%q,"time":200,"value":4}`, "短"),
		`{"type":"watermark","time":1000}`,
	}
	input := strings.Join(lines, "\n") + "\n"

	var refOut, refLate bytes.Buffer
	if err := RunAggregate(strings.NewReader(input), 1000, &refOut, &refLate); err != nil {
		t.Fatalf("one-shot reference failed: %v", err)
	}

	// Alternating one-byte and 4 KiB cuts.
	var cuts []int
	pos := 0
	small := true
	for pos < len(input) {
		step := 1
		if !small {
			step = 4096
		}
		small = !small
		pos += step
		if pos < len(input) {
			cuts = append(cuts, pos)
		}
	}

	var out, late bytes.Buffer
	if err := RunAggregate(newChunkReader(input, cuts...), 1000, &out, &late); err != nil {
		t.Fatalf("alternating-chunk run failed: %v", err)
	}
	if out.String() != refOut.String() {
		t.Fatalf("alternating chunks changed the window output:\n got: %q\nwant: %q", out.String(), refOut.String())
	}
	if late.String() != refLate.String() {
		t.Fatalf("alternating chunks changed the late output:\n got: %q\nwant: %q", late.String(), refLate.String())
	}
}

