// scanAggregateObject parses one complete JSON object record the way the
// aggregate entries read it and additionally reports how many of the object's
// own members decode to the field name "key". Members are counted in JSON
// source order with their decoded names, so "key" and a spelling such as
// "key" that decodes to key are the same field, while a "key" nested
// inside another member's object or array is not top-level and is skipped
// wholesale by decoding that value. A non-object, malformed JSON or trailing
// data is an error; callers keep the existing invalid-JSON wording for it, so
// the duplicate-key rule only applies to a record that parsed as one complete
// object. The returned map is exactly what json.Unmarshal into
// map[string]json.RawMessage produced before (a repeated member keeps its last
// value); the count is what lets callers reject that repetition instead.
func scanAggregateObject(line string) (map[string]json.RawMessage, int, error) {
	dec := json.NewDecoder(strings.NewReader(line))
	first, err := dec.Token()
	if err != nil {
		return nil, 0, err
	}
	delim, ok := first.(json.Delim)
	if !ok || delim != '{' {
		// Match the map unmarshal's report for JSON that is valid but not an
		// object, preserving the pre-existing error text for such input.
		var obj map[string]json.RawMessage
		if err := json.Unmarshal([]byte(line), &obj); err != nil {
			return nil, 0, err
		}
		return nil, 0, fmt.Errorf("expected a JSON object")
	}
	obj := make(map[string]json.RawMessage)
	keyCount := 0
	for dec.More() {
		nameToken, err := dec.Token()
		if err != nil {
			return nil, 0, err
		}
		name := nameToken.(string) // between { and }, object member names are JSON strings
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return nil, 0, err
		}
		obj[name] = raw
		if name == "key" {
			keyCount++
		}
	}
	if _, err := dec.Token(); err != nil { // the closing '}'
		return nil, 0, err
	}
	if _, err := dec.Token(); err != io.EOF {
		if err != nil {
			return nil, 0, err
		}
		return nil, 0, fmt.Errorf("invalid character after top-level value")
	}
	return obj, keyCount, nil
}

